namespace ks{namespace{PanelPublishPartialTest partialTest=nullptr;using T=PanelPublishTask;using S=T::Stage;struct Point{unsigned location,length;};Point point(S s){switch(s){case S::HoldSource:return{0x6d0,4};case S::HoldOutput:return{0x6d4,4};case S::LocateSource:return{0x6d8,6};case S::SetLatch:return{0x6de,2};case S::SetCount:return{0x6e0,4};case S::ReadShadow:return{0x6e4,2};case S::WriteData:return{0x6e6,2};case S::WriteLatch:return{0x6e8,2};case S::ClearStrobe:return{0x6ea,4};case S::HoldDelay:return{0x6ee,2};case S::SetDelay:return{0x6f0,4};case S::Tick:return{0x6f4,2};case S::RepeatDelay:return{0x6f6,2};case S::RestoreDelay:return{0x6f8,2};case S::SetStrobe:return{0x6fa,4};case S::NextLatch:return{0x6fe,2};case S::NextSlot:return{0x700,2};case S::RepeatSlots:return{0x702,2};case S::RestoreOutput:return{0x704,4};case S::RestoreSource:return{0x708,4};case S::Finish:return{0x70c,2};default:throw std::runtime_error("Invalid panel publish stage");}}}
bool PanelPublishCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0x6d0){if(selected)throw std::runtime_error("Overlapping panel publish");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel publish capacity");selected->emplace(h.getSP());++started;}if(!selected||point((**selected).task.stage()).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(stage).length);auto&v=h.regs;auto clock=[](T::Write){return 1u;};auto cost=t.nextClocks(clock);t.advanceBefore(cost,[&](T::Read r){return uint8_t(h.read8(r==T::Read::Shadow?0xffec1c+t.index():0xffff62));},[&](T::Write w,uint8_t value){if(w==T::Write::Strobe)h.write8(value,0xffff62);else f.store8(w==T::Write::Data?0xffff61:0xffff62,int8_t(value));},clock);auto hold=[&](auto value){f.push(value);(**selected).depth+=sizeof(value);};auto restore=[&](auto&value){f.pop(value);(**selected).depth-=sizeof(value);};switch(stage){case S::HoldSource:hold(v[5].er);break;case S::HoldOutput:hold(v[6].er);break;case S::LocateSource:f.move(v[5].er,0xffec1c);break;case S::SetLatch:f.move(v[6].rl,0x30);break;case S::SetCount:f.move(v[6].e,7);break;case S::ReadShadow:f.move(v[6].rh,t.data());v[5].er+=1;h.clockI(2);break;case S::HoldDelay:hold(v[0].r);break;case S::SetDelay:f.move(v[0].r,3);break;case S::Tick:f.inc(v[0].r,-1);break;case S::RestoreDelay:restore(v[0].r);break;case S::NextLatch:f.inc(v[6].rl,1);break;case S::NextSlot:f.inc(v[6].e,-1);break;case S::RestoreOutput:restore(v[6].er);break;case S::RestoreSource:restore(v[5].er);break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Finish)h.pc=h.makepc(point(t.stage()).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel publish clocks differ");return true;}}

